-- LUM-590: Lazy-cached SYSTEM-generated plain-language explanation for a
-- boundary crossing. Generated by LLM the first time a human asks (web panel
-- "Explain" button), then cached here for subsequent reads. NULL = not yet
-- generated. ADVISORY ONLY — never touches disposition or the DONE gate.
ALTER TABLE "boundary_crossings" ADD COLUMN IF NOT EXISTS "systemExplanation" TEXT;
